/**
 * Writes sanity/theme/tokens.generated.ts from the site's colour tokens in app/globals.css: the
 * Sanity UI palette for the Studio theme and hex values for the Studio's status components.
 *
 *   npm run studio:tokens
 *
 * Re-run after changing any token in app/globals.css; tests/unit/studio-theme.test.ts fails until
 * the generated file matches.
 */
import { writeFileSync } from "node:fs"
import path from "node:path"

import { readThemeTokens } from "../lib/design-tokens"
import { buildStudioPalette, buildStudioTokens } from "../lib/studio-palette"

const tokens = readThemeTokens()
const palette = buildStudioPalette(tokens)
const studioTokens = buildStudioTokens(tokens)

const file = `// Generated by scripts/studio-tokens.ts from app/globals.css. Do not edit by hand:
// run \`npm run studio:tokens\` after changing a token.

/** Sanity UI palette: the site's neutrals and status colours on Sanity's 50–950 ramps. */
export const palette = ${JSON.stringify(palette, null, 2)} as const

/** Site tokens as hex, per scheme, for the Studio's own components. */
export const tokens = ${JSON.stringify(studioTokens, null, 2)} as const
`

const out = path.join(process.cwd(), "sanity/theme/tokens.generated.ts")
writeFileSync(out, file)
console.log(`Wrote ${path.relative(process.cwd(), out)}`)
